<script setup lang="ts"> import { ref } from 'vue'; import { useRouter } from 'vue-router'; import { api, errorMessage } from '../api'; import { login } from '../auth'; const email=ref('admin@chevymania.local'), password=ref('ChangeMe123!'), loading=ref(false), error=ref(''); const router=useRouter(); async function submit(){ loading.value=true; error.value=''; try { const {data}=await api.post('/auth/login',{email:email.value,password:password.value}); login(data.token,data.user); router.push('/'); } catch(e){error.value=errorMessage(e)} finally {loading.value=false} } </script>
<template><v-row justify="center"><v-col cols="12" sm="8" md="5"><v-card title="Acceso a Chevymania" class="mt-12"><v-card-text><v-alert v-if="error" type="error" class="mb-4">{{error}}</v-alert><v-form @submit.prevent="submit"><v-text-field v-model="email" label="Correo" type="email" :rules="[v=>!!v || 'Requerido']"/><v-text-field v-model="password" label="Contraseña" type="password" :rules="[v=>v.length>=8 || 'Mínimo 8 caracteres']"/><v-btn type="submit" color="primary" block :loading="loading">Iniciar sesión</v-btn></v-form></v-card-text></v-card></v-col></v-row></template>
